CREDIT='<p class="text-xs opacity-60 mt-4">Képek: Wikimedia Commons, szabad licenc — <a class="underline" href="../CREDITS.md">forrásmegjelölés</a>. Minden szám és grafikon <b>mintaadat</b>, az árak <b>példák</b>.</p>'
def bars(color,track,txt="text-sm"):
  o=""
  for t,rows in DEMO:
    o+=f'<div><h4 class="font-semibold mb-3">{t}</h4>'
    for l,v in rows: o+=f'<div class="{txt} flex items-center gap-3 mb-2"><span class="w-32 shrink-0">{l}</span><div class="flex-1 h-2.5 rounded-full {track}"><div class="h-2.5 rounded-full {color}" style="width:{v*2.5}%"></div></div><span class="w-10 text-right tabular-nums">{v}%</span></div>'
    o+='</div>'
  return f'<div class="grid md:grid-cols-2 gap-8">{o}</div><p class="text-xs opacity-60 mt-4">Mintaadat — a végleges arányok KSH-adatokból kerülnek beállításra.</p>'
def faq(cls):
  return "".join(f'<details class="{cls}"><summary class="cursor-pointer font-semibold">{q}</summary><p class="mt-3 opacity-80">{a}</p></details>' for q,a in FAQ)
def report(card,accent,acc2):
  return f'''<div class="{card}"><div class="flex justify-between items-center mb-4"><h4 class="font-bold">Mintariport: „Vásárolnád 4 990 Ft-ért?”</h4><span class="text-xs px-2 py-1 rounded {acc2}">Mintaadat</span></div>
<div class="grid grid-cols-3 gap-4 text-center mb-6">{"".join(f'<div><div class="text-3xl font-bold {accent}">{v}</div><div class="text-xs opacity-70">{l}</div></div>' for v,l in [("41%","biztosan / valószínűleg"),("3 990 Ft","optimális ár"),("18–29","legnyitottabb korcsoport")])}</div>
<svg viewBox="0 0 300 110" class="w-full"><g fill="currentColor">{"".join(f'<rect x="{12+i*48}" y="{100-h}" width="30" height="{h}" rx="4" opacity="{0.35+i*0.12}"/><text x="{27+i*48}" y="{95-h}" font-size="9" text-anchor="middle">{h//1}%</text>' for i,h in enumerate([52,47,40,33,22,14][:6]))}</g></svg>
<p class="text-xs opacity-60 mt-2">Vásárlási hajlandóság korcsoportonként (18–29 … 75+) — illusztráció</p></div>'''
def mosaic(n=120,size="w-8 h-8"):
  cols=["#f4c7a1","#e0ac69","#c68642","#f1d3b3","#d9a066"];hair=["#2b1b10","#5a3825","#a0703c","#d8c3a5","#777"]
  o=""
  for i in range(n):
    s=random.choice(cols);h=random.choice(hair);bg=random.choice(["#fde68a","#bfdbfe","#fecaca","#bbf7d0","#ddd6fe","#fed7aa"])
    o+=f'<svg class="{size}" viewBox="0 0 32 32"><rect width="32" height="32" rx="8" fill="{bg}"/><circle cx="16" cy="13" r="6" fill="{s}"/><path d="M10 12a6 6 0 0 1 12 0q-6-4-12 0" fill="{h}"/><path d="M5 32a11 9 0 0 1 22 0" fill="{random.choice(["#1e3a8a","#9f1239","#065f46","#374151","#7c2d12"])}"/></svg>'
  return o
HEAD=lambda title,extra="":f'''<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>magorg.hu — {title}</title><script src="https://cdn.tailwindcss.com"></script>{extra}<meta name="robots" content="noindex"></head>'''
NAVL=["Hogyan működik","Avatar-panel","Szolgáltatások","Árak","GYIK"]
IDS=["hogyan","panel","szolg","arak","gyik"]
def nav(cls,brand,btn):
  return f'<nav class="{cls}"><div class="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">{brand}<div class="hidden md:flex gap-6 text-sm">{"".join(f"<a href=#{i}>{l}</a>" for l,i in zip(NAVL,IDS))}</div><a href="#kapcsolat" class="{btn}">Ajánlatkérés</a></div></nav>'
def page(n,html):
  os.makedirs(f"site/{n}",exist_ok=True);open(f"site/{n}/index.html","w").write(html)
def sec(id,cls,inner): return f'<section id="{id}" class="{cls}"><div class="max-w-6xl mx-auto px-6">{inner}</div></section>'
def common(T):
  s=sec("hogyan",T["sec"],f'<h2 class="{T["h2"]}">Hogyan működik?</h2><div class="grid md:grid-cols-3 gap-6 mt-10">'+"".join(f'<div class="{T["card"]}"><div class="{T["num"]}">{i+1}</div><h3 class="text-xl font-bold mt-4">{a}</h3><p class="mt-2 opacity-80">{b}</p></div>' for i,(a,b) in enumerate(STEPS))+'</div>')
  s+=sec("panel",T["sec2"],f'<div class="grid lg:grid-cols-5 gap-10 items-start"><div class="lg:col-span-2"><h2 class="{T["h2"]}">A 3000 fős avatar-panel</h2><p class="mt-4 opacity-80">Minden avatar egy statisztikailag felépített „magyar ember”: kora, neme, lakóhelye, végzettsége, jövedelme és értékrendje a népszámlálási arányokat követi. Együtt Magyarország kicsinyített mása — amely akár a napi hírekre is reagál.</p>{T.get("panelx","")}</div><div class="lg:col-span-3 {T["card"]}">{bars(T["bar"],T["track"])}</div></div>')
  s+=sec("szolg",T["sec"],f'<h2 class="{T["h2"]}">Szolgáltatások</h2><div class="grid md:grid-cols-3 gap-6 mt-10">'+"".join(f'<div class="{T["card"]}"><h3 class="text-lg font-bold">{a}</h3><p class="mt-2 opacity-80 text-sm">{b}</p></div>' for a,b in SERV)+f'<div class="{T["card"]} flex items-center"><p class="font-semibold">Töredékáron, a hagyományos kutatás idejének töredéke alatt.</p></div></div>')
  s+=sec("riport",T["sec2"],f'<div class="grid md:grid-cols-2 gap-10 items-center"><div><h2 class="{T["h2"]}">Így néz ki egy riport</h2><p class="mt-4 opacity-80">Számok, szegmensek és — ami a legtöbbet ér — az avatarok saját szavaival megfogalmazott indoklások. Minden riport javaslatokkal zárul.</p><blockquote class="mt-6 border-l-4 pl-4 italic opacity-80">„Drágának tartom, de ha a gyerekem iskolájában is használják, megvenném.” <span class="block text-xs not-italic mt-1">— avatar #1842, 41 éves nő, Pest megye · Mintaadat</span></blockquote></div>{report(T["card"],T["acc"],T["badge"])}</div>')
  s+=sec("arak",T["sec"],f'<h2 class="{T["h2"]}">Árak</h2><p class="opacity-70 mt-2">Példa árak — a végleges árazás egyeztetés alatt.</p><div class="grid md:grid-cols-3 gap-6 mt-10">'+"".join(f'<div class="{T["card"]}"><span class="text-xs px-2 py-1 rounded {T["badge"]}">példa</span><h3 class="text-xl font-bold mt-3">{a}</h3><div class="text-3xl font-bold mt-2 {T["acc"]}">{p}</div><p class="mt-2 opacity-80 text-sm">{d}</p></div>' for a,p,d in PRICE)+'</div>')
  s+=sec("gyik",T["sec2"],f'<h2 class="{T["h2"]}">Gyakori kérdések</h2><div class="mt-8 space-y-3">{faq(T["card"])}</div>')
  s+=sec("kapcsolat",T["cta"],f'<div class="text-center"><h2 class="{T["h2"]}">Tudd meg még ma, mit gondol Magyarország.</h2><p class="mt-4 opacity-80">Írd le a kérdésedet, 24 órán belül jelentkezünk egy ajánlattal.</p><form class="mt-8 max-w-xl mx-auto flex flex-col sm:flex-row gap-3" onsubmit="event.preventDefault();this.innerHTML=\'<p class=font-semibold>Köszönjük! (minta űrlap)</p>\'"><input required type="email" placeholder="E-mail címed" class="flex-1 px-4 py-3 rounded-lg text-gray-900 border"><button class="{T["btn"]}">Ajánlatot kérek</button></form>{CREDIT}</div>')
  return s
FOOT=lambda c:f'<footer class="{c} py-8 text-center text-sm">© magorg.hu — mintaoldal, nem végleges tartalom</footer>'
